import React from "react";

export default function DevisCard({ projet }) {
    return (
        <div className="border rounded shadow p-4 bg-yellow-50 mb-4">
            <h3 className="text-lg font-bold mb-2">Devis du projet</h3>
            <p><strong>ID Projet :</strong> {projet.id}</p>
            <p><strong>Type :</strong> {projet.typeConstruction}</p>
            <p><strong>Superficie :</strong> {projet.superficieConstruite} m²</p>
            <p><strong>Coût total :</strong> {projet.coutTotal} DH</p>
            <p><strong>Statut :</strong> {projet.statut}</p>
        </div>
    );
}
